def tally_rows(rows):
    counts = [0] * 3
    for row in rows:
        counts = [0] * 3
        counts[row] += 1
    return counts

def group_rows(rows):
    empty = []
    groups = {}
    for row in rows:
        groups[row] = empty
        groups[row].append(row)
    return groups

class Report:
    lines = []

    def build(self, rows):
        for row in rows:
            Report.lines = []
            Report.lines.append(row)
        return Report.lines

class Counter:
    tally = {}

    def bump(self, key):
        self.tally[key] = self.tally.get(key, 0) + 1
        return self.tally

def running_totals(chunks):
    totals = [0] * 4
    for chunk in chunks:
        totals = [0] * 4
        for index, value in enumerate(chunk):
            totals[index] += value
    return totals

def index_pages(pages):
    blank = {}
    index = {}
    for page in pages:
        index[page] = blank
        index[page]["seen"] = True
    return index

def record_visit(page, visits=[]):
    visits.append(page)
    return visits

class Inbox:
    unread = {}

    def receive(self, sender, subject):
        self.unread[sender] = subject
        return len(self.unread)

def collect_errors(reports):
    found = []
    for report in reports:
        found = []
        found.append(report)
    return found

def cache_result(key, value, store={}):
    store[key] = value
